// GetSummaryFields returns the summary fields for a resource type, or nil if the
// type is unknown.
//
// The returned slice is a copy: handing back the stored one let a caller reorder or
// overwrite the specification's own data for every other caller in the process,
// which is the same hazard as the exported map and not fixed by hiding it alone.
// Use IsSummaryField for a membership test — it allocates nothing.
func GetSummaryFields(resourceType string) []string {
	fields, ok := summaryFields[resourceType]
	if !ok {
		return nil
	}
	out := make([]string, len(fields))
	copy(out, fields)
	return out
}

// IsSummaryField returns true if the field is a summary field for the resource type.
func IsSummaryField(resourceType, fieldName string) bool {
	fields := summaryFields[resourceType]
	for _, f := range fields {
		if f == fieldName {
			return true
		}
	}
	return false
}
